    [Fact]
    public void Execute_UnknownOperation_Throws()
    {
        var machine = new CashMachine(new MoneyDispenser(Full));

        Assert.Throws<ArgumentException>(() => machine.Execute(new AccountState(0, 0), new UnknownOperation()));
    }

